import sys
from datetime import date, timedelta

RATE = {"book": 0.5, "dvd": 1.0, "magazine": 0.2}


def parse(text):
    y, m, d = map(int, text.split("-"))
    return date(y, m, d)


def move_due_date_to_next_monday(due_date):
    while due_date.weekday() == 6:  # Sunday is 6
        due_date += timedelta(days=1)
    return due_date


def calculate_late_fee(item_type, due_date_moved, returned_date=None, asof_date=None):
    if returned_date is None:
        returned_date = asof_date
    days_late = (returned_date - due_date_moved).days
    if days_late <= 0:
        return 0.0
    days_over_grace = max(0, days_late - 3)
    fee = days_over_grace * RATE[item_type]
    return min(fee, 10.00)


def main():
    lines = sys.stdin.read().splitlines()
    if not lines:
        return

    asof_line = lines[0]
    if not asof_line.startswith("asof "):
        print("Invalid input format")
        return

    asof_date = parse(asof_line.split()[1])
    totals = {}

    for line in lines[1:]:
        if not line.strip():
            continue
        fields = line.split()
        if len(fields) != 4:
            print(f"Skipping invalid line: {line}")
            continue
        member, item_type, due_str, returned_str = fields
        try:
            due_date = parse(due_str)
        except ValueError:
            print(f"Skipping invalid date: {due_str}")
            continue
        if returned_str == "-":
            returned_date = asof_date
        else:
            try:
                returned_date = parse(returned_str)
            except ValueError:
                print(f"Skipping invalid return date: {returned_str}")
                continue
        due_date_moved = move_due_date_to_next_monday(due_date)
        fee = calculate_late_fee(item_type, due_date_moved, returned_date, asof_date)
        totals[member] = totals.get(member, 0.0) + fee

    members = sorted(totals.keys())
    for member in members:
        print(f"{member} {totals[member]:.2f}")
    print(f"total {sum(totals.values()):.2f}")


if __name__ == "__main__":
    main()
